def transform(grid):
    g = np.array(grid).copy()
    H, W = g.shape
    bg = background(g)
    # divider column between legend (left) and frame (right)
    cols = [x for x, c in dividers(g)["cols"] if c != bg]
    d = min(cols)
    # frame border colour = most common colour on the frame's border
    border = list(g[0, d+1:]) + list(g[H-1, d+1:]) + list(g[:, d+1]) + list(g[:, W-1])
    fbg = max(set(border), key=border.count)
    rows, colm = {}, {}
    for y in range(1, H-1):
        for c in (g[y, d+1], g[y, W-1]):
            if c != fbg:
                rows.setdefault(c, set()).add(y)
    for x in range(d+2, W-1):
        for c in (g[0, x], g[H-1, x]):
            if c != fbg:
                colm.setdefault(c, set()).add(x)
    left = g[:, :d]
    # motifs ordered by their topmost row; paint bottom-first so the upper motif ends on top
    motifs = []
    for c in set(left.flatten()) - {bg}:
        cells = list(zip(*np.where(left == c)))
        motifs.append((bbox(cells)[0], c, cells))
    motifs.sort(reverse=True)
    for _, c, cells in motifs:
        if c in rows and c in colm:
            y0, x0, y1, x1 = bbox(cells)
            cy, cx = (y0 + y1) // 2, (x0 + x1) // 2
            for r in sorted(rows[c]):
                for cc in sorted(colm[c]):
                    for (y, x) in cells:
                        yy, xx = r + y - cy, cc + x - cx
                        if 0 <= yy < H and 0 <= xx < W:
                            g[yy, xx] = c
            emit(g, f"stamp the colour-{c} motif centred on every crossing of its marker row(s) {sorted(rows[c])} and column(s) {sorted(colm[c])}")
            for (y, x) in cells:
                g[y, x] = bg
            emit(g, f"erase the stamped colour-{c} motif from the legend")
    emit(g, "final: motifs without a marker row and column stay in the legend")
    return g
